/**
 * Server-side course registry: assessment policy and question generation.
 * Question banks (and therefore answer keys) are only ever loaded here.
 *
 *  - legacy courses 01-04: data and banks under src/services/db (also used by the
 *    client for lesson content; see vite.config.js, which keeps banks out of the
 *    browser bundle)
 *  - library courses 05-22: generated by scripts/import_library_courses.mjs into
 *    api/_data/library
 */
import crypto from 'crypto';
import { LIBRARY_SPECS, LIBRARY_BANK_LOADERS } from '../_data/library/index.js';

const LEGACY = {
  crs_cyber_intro_01: { code: 'C01', finalCount: 50 },
  crs_cyber_net_02: { code: 'C02', finalCount: 50 },
  crs_cyber_admin_03: { code: 'C03', finalCount: 50 },
  crs_cyber_python_04: { code: 'C04', finalCount: 60 },
};

let legacyPromise = null;
function loadLegacy() {
  if (!legacyPromise) {
    legacyPromise = Promise.all([
      import('../../src/services/db/cyberCourses.js'),
      import('../../src/services/db/questionBanks/questionBankEngine.js'),
    ]);
  }
  return legacyPromise;
}

export const MAX_ATTEMPTS = 3;
export const LOCKOUT_HOURS = 24;
export const GRACE_SECONDS = 120;

const specCache = new Map();

/** Returns the assessment spec for a course, or null for unknown courses. */
export async function getCourseSpec(courseId) {
  if (specCache.has(courseId)) return specCache.get(courseId);
  let spec = null;
  const lib = LIBRARY_SPECS.find((s) => s.id === courseId);
  if (lib) {
    spec = { ...lib, source: 'library' };
  } else if (LEGACY[courseId]) {
    const [{ CYBER_COURSES }] = await loadLegacy();
    const c = CYBER_COURSES.find((x) => x.id === courseId);
    if (c) {
      const fa = c.final_assessment || {};
      spec = {
        id: c.id,
        code: LEGACY[courseId].code,
        title: c.title,
        source: 'legacy',
        modules: c.modules
          .map((m, i) => ({ m, i }))
          .filter(({ m }) => m.quiz)
          .map(({ m, i }) => ({
            number: i + 1,
            quizId: m.quiz.id,
            title: m.quiz.title || m.title,
            passingScore: m.quiz.passing_score || m.quiz.pass_threshold || 80,
            count: 20,
            timeLimitMinutes: 30,
            tokenBounty: m.quiz.token_bounty || 100,
          })),
        final: {
          id: fa.id,
          title: fa.title || `${c.title} - Final Assessment`,
          passingScore: fa.passing_score || 80,
          // the published course page states this number; serve exactly that many
          count: fa.total_questions || LEGACY[courseId].finalCount,
          timeLimitMinutes: fa.time_limit_minutes || 60,
          tokenBounty: 300,
          credentialTitle: fa.credential_title || c.milestone_cert || `Certificate of Completion: ${c.title}`,
          skills: fa.skills_validated || (c.skills || []).slice(0, 6),
        },
      };
    }
  }
  if (spec) specCache.set(courseId, spec);
  return spec;
}

export function findQuiz(spec, quizId) {
  if (!spec || !quizId) return null;
  if (spec.final?.id === quizId) return { kind: 'final', ...spec.final, quizId: spec.final.id };
  const mod = spec.modules.find((m) => m.quizId === quizId);
  return mod ? { kind: 'module', ...mod } : null;
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/** Library bank question -> session question with shuffled, opaque option ids. */
function fromLibrary(q) {
  const order = shuffle([0, 1, 2, 3]);
  const options = order.map((orig, pos) => ({ id: `${q.id}-o${pos}`, text: q.options[orig], orig }));
  return {
    id: q.id,
    text: q.q,
    topic: q.topic,
    explanation: q.explanation || '',
    options: options.map(({ id, text }) => ({ id, text })),
    correctOptionId: options.find((o) => o.orig === q.correct).id,
  };
}

// Options whose meaning depends on their position must keep the original order.
const ORDER_DEPENDENT = /\b(all|none|both) of the above\b|^both [a-d] and [a-d]\b|\b(options?|answers?) [a-d]\b|^\(?[a-d]\)? (and|&) \(?[a-d]\)?/i;

/**
 * Legacy engine question ({options:[{id,text,is_correct}]}) -> session question.
 * Options are shuffled per session with opaque ids (like library questions), so a
 * photo of one student's screen does not line up with anyone else's.
 */
function fromLegacy(q) {
  const raw = (q.options || []).map((o) => ({ text: o.text, ok: Boolean(o.is_correct) }));
  const ordered = raw.some((o) => ORDER_DEPENDENT.test(String(o.text))) ? raw : shuffle(raw);
  const options = ordered.map((o, pos) => ({ id: `${q.id}-o${pos}`, text: o.text, ok: o.ok }));
  const correct = options.find((o) => o.ok);
  return {
    id: String(q.id),
    text: q.text || q.question || q.q,
    topic: q.topic || '',
    explanation: q.explanation || '',
    options: options.map(({ id, text }) => ({ id, text })),
    correctOptionId: correct ? correct.id : null,
  };
}

/** Generates a fresh randomised question set for a quiz (answers included - server use only). */
export async function generateQuestions(spec, quiz) {
  if (spec.source === 'library') {
    const bank = (await LIBRARY_BANK_LOADERS[spec.id]()).default;
    if (quiz.kind === 'module') {
      return shuffle(bank.modules[quiz.number] || []).map(fromLibrary);
    }
    // final: every course-level question + a stratified sample of module questions
    const perModule = Object.values(bank.modules).map((qs) => shuffle(qs));
    const sampled = [];
    let round = 0;
    while (sampled.length < quiz.fromModules && round < 50) {
      for (const qs of shuffle(perModule)) {
        if (sampled.length >= quiz.fromModules) break;
        if (qs[round]) sampled.push(qs[round]);
      }
      round++;
    }
    return shuffle([...bank.course, ...sampled]).map(fromLibrary);
  }

  const [, engine] = await loadLegacy();
  const isFinal = quiz.kind === 'final';
  const raw = engine.getOrGenerateQuizQuestions(null, quiz.quizId, isFinal ? 1 : quiz.number, isFinal, spec.id, true);
  const questions = raw.map(fromLegacy).filter((q) => q.correctOptionId && q.options.length >= 2);
  return isFinal ? questions.slice(0, quiz.count) : questions;
}

/** Public, answer-free view of a session's questions. */
export function publicQuestions(questions) {
  return questions.map((q) => ({ id: q.id, text: q.text, topic: q.topic, options: q.options }));
}

export function allCourseIds() {
  return [...Object.keys(LEGACY), ...LIBRARY_SPECS.map((s) => s.id)];
}
